<?php
require_once __DIR__ . '/inc/mother_session.php';
$q=$db->prepare('SELECT title,content_body,category topic,trimester,language,created_at FROM tbl_education_content WHERE is_active=1 AND language=? UNION ALL SELECT title,content_body,content_type topic,trimester,language,created_at FROM tbl_nutrition_content WHERE is_active=1 AND language=? ORDER BY created_at DESC');$q->execute([$language,$language]);$allContent=$q->fetchAll(PDO::FETCH_ASSOC);
$topics=[];foreach($allContent as $item){$topic=trim((string)$item['topic']);if($topic!==''&&!in_array($topic,$topics,true))$topics[]=$topic;}
$category=trim((string)($_GET['topic']??''));$education=array_values(array_filter($allContent,fn($item)=>$category===''||$item['topic']===$category));
$pregnancyQ=$db->prepare("SELECT trimester FROM (SELECT CASE WHEN lmp IS NOT NULL THEN CASE WHEN TIMESTAMPDIFF(DAY,lmp,CURDATE())<98 THEN '1' WHEN TIMESTAMPDIFF(DAY,lmp,CURDATE())<196 THEN '2' ELSE '3' END ELSE 'all' END trimester FROM tbl_pregnancies WHERE mother_id=? AND pregnancy_status='active' ORDER BY created_at DESC LIMIT 1) p");$pregnancyQ->execute([$motherId]);$trimester=$pregnancyQ->fetchColumn()?:'all';
$page_title=$t('Health education');include 'inc/links.php';include 'inc/header.php';
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php'; ?><section role="main" class="content-body"><?php include 'inc/inner-header.php'; ?>
<section class="panel"><header class="panel-heading"><h2 class="panel-title"><?=$t('Maternal health and nutrition guidance')?></h2></header><div class="panel-body"><p><?=$t('This page shows content published by your care team in your selected language.')?></p><form method="get" class="form-inline"><label for="education-topic"><?=$t('Filter by topic')?></label> <select id="education-topic" class="form-control" name="topic"><option value=""><?=$t('All topics')?></option><?php foreach($topics as $topic): ?><option value="<?=$e($topic)?>" <?=$category===$topic?'selected':''?>><?=$e($t(ucwords(str_replace('_',' ',$topic))))?></option><?php endforeach; ?></select> <button class="btn btn-default"><?=$t('Apply filter')?></button></form></div></section>
<?php foreach($education as $item): ?><section class="panel"><header class="panel-heading"><h2 class="panel-title"><?=$e($item['title'])?></h2><small><?=$e($t(ucwords(str_replace('_',' ',$item['topic']))))?><?php if($item['trimester']&&$item['trimester']!=='all'): ?> · <?=$t('Trimester')?> <?=$e($item['trimester'])?><?php endif; ?></small></header><div class="panel-body"><p><?=nl2br($e($item['content_body']))?></p><small class="text-muted"><?=$e(strtoupper($item['language']))?></small></div></section><?php endforeach; ?>
<?php if(!$education): ?><div class="alert alert-info"><?=$t('Your care team has not published guidance for your preferred language yet. Contact them for trusted advice.')?></div><?php endif; ?>
</section></div><?php include 'inc/footer.php';include 'inc/scripts.php'; ?>
